\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{booktabs}

\title{Budget-Constrained Deep Reinforcement Learning for
Arterial Traffic Signal Control}
\author{K.~Osei and L.~Marchetti}
\date{May 2026}

\begin{document}
\maketitle

\begin{abstract}
We study deep reinforcement learning for coordinated signal
control on urban arterials under a strict training budget. A
parameter-shared agent with a corridor-level reward trains in
under nine hours of simulation and matches or exceeds a tuned
actuated baseline on three of four test corridors.
\end{abstract}

\section{Introduction}
Signal timing remains one of the cheapest levers for urban
congestion. Learning-based controllers promise adaptive
coordination without hand-tuned plans, but their training cost
and sim-to-real gap keep deployments rare. We ask how much of
the reported benefit survives when the training budget is
capped at what a municipal traffic office could plausibly run.

\input{sections/background}

\section{Method}
The corridor is modelled as a graph of signalised junctions. A
single policy is shared across junctions, conditioned on local
queue estimates and the phase of neighbouring junctions. The
reward combines corridor throughput with a penalty on side
street maximum delay. Training uses proximal policy
optimisation with early stopping on a held-out demand
scenario.

\section{Evaluation}
We evaluate on four arterial corridors with calibrated evening
peak demand, comparing against a tuned actuated controller and
a fixed-time coordination plan. Metrics are corridor travel
time, side-street maximum delay, and number of stops.

\section{Conclusion}
Under a nine-hour training budget, the learned controller
beats the actuated baseline on three of four corridors and
never degrades side-street service by more than a small
margin. The remaining failure case is a corridor with heavy
mid-block demand, which we leave to future work.
\end{document}
